"""Elasticsearch: mappings, Mistral inference endpoints, geo_match enrich pipeline, and idempotent writes."""

import logging
from datetime import UTC, datetime

from elasticsearch import ApiError, Elasticsearch, NotFoundError
from elasticsearch.helpers import bulk

from highground.config import settings

log = logging.getLogger("highground.store")
KW, DATE, GEO, BOOL, FLOAT, TEXT = ({"type": t} for t in ("keyword", "date", "geo_point", "boolean", "float", "text"))

MAPPINGS = {
    "reports": {"case_id": KW, "category": KW, "subcategory": KW, "category_source": KW, "service_code": KW, "status": KW,
                "requested_at": DATE, "updated_at": DATE, "closed_at": DATE, "location": GEO, "h3_9": KW, "address": TEXT,
                "neighborhood": KW, "description": TEXT, "media_url": {"type": "keyword", "index": False}, "zone_100yr": BOOL, "slr24": BOOL,
                "vision": {"properties": {"water_visible": BOOL, "confidence": FLOAT}}},
    "zones": {"layer": KW, "name": KW, "geometry": {"type": "geo_shape"}},
    "conditions": {"@timestamp": DATE, "kind": KW, "point": KW, "rain_mm": FLOAT, "gust_kmh": FLOAT, "forecast": BOOL, "value": FLOAT,
                   "tide_type": KW, "event": KW, "headline": TEXT, "valid_from": DATE, "valid_to": DATE, "issued_at": DATE, "source": KW, "replay": KW},
    "incidents": {"type": KW, "location": GEO, "h3_9": KW, "place": TEXT, "flooding": BOOL, "started_at": DATE},
    "places": {"kind": KW, "name": {"type": "search_as_you_type"}, "alt": {"type": "search_as_you_type"}, "location": GEO, "neighborhood": KW},
    "profiles": {"h3_9": KW, "in_100yr": BOOL, "slr24": BOOL, "reports_5y": {"type": "integer"}, "storm_reports_5y": {"type": "integer"},
                 "storm_days_5y": {"type": "integer"}, "neighborhood": KW, "centroid": GEO},
    "risk": {"h3_9": KW, "level": KW, "rank": {"type": "byte"}, "score": FLOAT, "reasons": {"type": "object", "enabled": False},
             "as_of": DATE, "polygon": {"type": "geo_shape"}},
    "guides": {"url": KW, "lang": KW, "title": TEXT, "body": TEXT, "content": TEXT},
    "feeds": {"last_ok": DATE, "watermark": DATE, "error": TEXT},
}  # fmt: skip
SETTINGS = {"profiles": {"index.mode": "lookup"}}  # joinable from ES|QL LOOKUP JOIN
PIPELINE, POLICY = "reports-enrich", "zones-policy"
EMBED, CHAT, COMPLETION = "mistral-embeddings", "mistral-chat", "mistral-completion"


class Store:
    def __init__(self, client: Elasticsearch | None = None):
        cfg = settings()
        self.cfg = cfg
        self.es = client or (Elasticsearch(cfg.es_url, api_key=cfg.es_api_key, request_timeout=60) if cfg.es_api_key else Elasticsearch(cfg.es_url, request_timeout=60))

    def ix(self, name: str) -> str:
        return self.cfg.ix(name)

    def write(self, name: str, docs: list[dict], pipeline: bool = False, merge_fn=None, refresh=False) -> int:
        if not docs:
            return 0
        if merge_fn:
            ids = list({d["_id"] for d in docs})
            existing = {}
            for i in range(0, len(ids), 1000):
                try:
                    for d in self.es.mget(index=self.ix(name), ids=ids[i : i + 1000])["docs"]:
                        if d.get("found"):
                            existing[d["_id"]] = d["_source"]
                except NotFoundError:
                    pass
            merged = {}
            for d in docs:
                merged[d["_id"]] = merge_fn(merged.get(d["_id"]) or existing.get(d["_id"]), d)
            docs = [{**v, "_id": k} for k, v in merged.items()]
        actions = [{"_index": self.ix(name), "_id": d["_id"], "_source": {k: v for k, v in d.items() if k != "_id"}} for d in docs]
        use = self.ix(PIPELINE) if pipeline and self.has_pipeline() else None
        ok, errors = bulk(self.es.options(request_timeout=180), actions, pipeline=use, refresh=refresh, chunk_size=1000, raise_on_error=False)
        if errors:  # keep going: one malformed polygon or row must not drop the rest of the batch
            log.warning("%d/%d rejected in %s: %s", len(errors), len(actions), name, str(errors[0])[:200])
        return ok

    def has_pipeline(self) -> bool:
        try:
            self.es.ingest.get_pipeline(id=self.ix(PIPELINE))
            return True
        except NotFoundError:
            return False

    def search(self, name: str, **body) -> dict:
        return self.es.search(index=self.ix(name), **body).body

    def esql(self, query: str, params: list | None = None) -> list[dict]:
        r = self.es.esql.query(query=query, params=params or []).body
        cols = [c["name"] for c in r["columns"]]
        return [dict(zip(cols, row, strict=False)) for row in r["values"]]

    def feed_state(self, name: str) -> dict:
        try:
            return self.es.get(index=self.ix("feeds"), id=name)["_source"]
        except NotFoundError:
            return {}

    def save_feed(self, name: str, state: dict) -> None:
        self.es.index(index=self.ix("feeds"), id=name, document=state)


def setup(s: Store) -> dict:
    out = {"inference": {}}
    if s.cfg.has_mistral:  # Mistral models as Elasticsearch inference endpoints (hack night guide names)
        for task, eid, model in (("text_embedding", EMBED, s.cfg.model_embed), ("chat_completion", CHAT, s.cfg.model_large),
                                 ("completion", COMPLETION, s.cfg.model_small)):  # fmt: skip
            try:
                s.es.inference.get(task_type=task, inference_id=eid)
            except NotFoundError:
                try:
                    s.es.inference.put(task_type=task, inference_id=eid, inference_config={"service": "mistral", "service_settings": {"api_key": s.cfg.mistral_api_key, "model": model}})
                except ApiError as exc:
                    log.warning("endpoint %s: %s", eid, exc)
                    continue
            out["inference"][eid] = True
    created = []
    for name, props in MAPPINGS.items():
        idx = s.ix(name)
        if s.es.indices.exists(index=idx):
            continue
        props = dict(props)
        if name == "guides" and out["inference"].get(EMBED):
            props["content"] = {"type": "semantic_text", "inference_id": EMBED}
        s.es.indices.create(index=idx, mappings={"properties": props}, settings=SETTINGS.get(name))
        created.append(idx)
    out["created"] = created
    return out


def enrich_pipeline(s: Store) -> None:
    """geo_match enrich: tag every 311 report with flood zone / sea-level-rise zone / neighborhood at ingest."""
    for fn, kw in ((s.es.ingest.delete_pipeline, {"id": s.ix(PIPELINE)}), (s.es.enrich.delete_policy, {"name": s.ix(POLICY)})):
        try:
            fn(**kw)
        except NotFoundError:
            pass
    s.es.enrich.put_policy(name=s.ix(POLICY), geo_match={"indices": s.ix("zones"), "match_field": "geometry", "enrich_fields": ["layer", "name"]})
    s.es.enrich.execute_policy(name=s.ix(POLICY), wait_for_completion=True)
    s.es.ingest.put_pipeline(id=s.ix(PIPELINE), processors=[
        {"enrich": {"policy_name": s.ix(POLICY), "field": "location", "target_field": "z", "shape_relation": "INTERSECTS", "max_matches": 16, "ignore_missing": True, "ignore_failure": True}},
        {"script": {"ignore_failure": True, "source": """
            ctx.zone_100yr = false; ctx.slr24 = false;
            if (ctx.z != null) { for (def m : (ctx.z instanceof List ? ctx.z : [ctx.z])) {
              if (m.layer == '100yr') ctx.zone_100yr = true; if (m.layer == 'slr24') ctx.slr24 = true;
              if (m.layer == 'neighborhood' && ctx.neighborhood == null) ctx.neighborhood = m.name; } ctx.remove('z'); }"""}},
        {"set": {"field": "ingested_at", "value": "{{{_ingest.timestamp}}}"}},
    ])  # fmt: skip


def run_feed(s: Store, name: str, http, now: datetime | None = None) -> dict:
    from highground.feeds import FEEDS, merge

    now = now or datetime.now(UTC)
    _, index, fetch = FEEDS[name]
    st = s.feed_state(name)
    since = datetime.fromisoformat(st["watermark"]) if st.get("watermark") else None
    try:
        docs = fetch(http, since, now)
        n = s.write(index, docs, pipeline=index == "reports", merge_fn=merge if index == "reports" else None)
        s.save_feed(name, {"last_ok": now.isoformat(), "watermark": now.isoformat() if name == "open311" else None, "rows": n, "error": None, "fails": 0})
        return {"feed": name, "rows": n}
    except Exception as exc:  # noqa: BLE001 - recorded, never crashes the worker
        s.save_feed(name, {**st, "error": f"{type(exc).__name__}: {exc}"[:300], "fails": st.get("fails", 0) + 1, "last_try": now.isoformat()})
        return {"feed": name, "error": str(exc)[:200]}

"""Live + historical feeds, normalized to Elasticsearch docs. One runner handles watermarks and failures.

SF Open311 (real-time 311), DataSF 311 (nightly history, authoritative subtypes), NWS alerts, NOAA tides,
Open-Meteo rain/gusts, CHP road incidents. All timestamps stored as UTC.
"""

import re
import xml.etree.ElementTree as ET
from datetime import UTC, datetime, timedelta
from zoneinfo import ZoneInfo

import httpx

from highground.geo import POINTS, cell, in_sf

PT = ZoneInfo("America/Los_Angeles")
UA = {"User-Agent": "HighGround-SF/hacknight"}
SF_UGC = ("CAZ006", "CAZ508", "CAZ509", "CAC075")  # NWS zones: SF city, Bay shoreline, Peninsula coast, county

_FLOOD = re.compile(r"\b(flood\w*|standing water|pond\w*|puddl\w*|underwater|inundat\w*|overflow\w*|water (is )?(rising|pooling|over))\b", re.IGNORECASE)
_DRAIN = re.compile(r"\b(catch ?basin|storm ?drain|drain\w*|clogged|grate)\b", re.IGNORECASE)
_SEWER = re.compile(r"\b(sewage|sewer|back ?up|backed up|toilet|odou?r|smell\w*|manhole)\b", re.IGNORECASE)
_LEAK = re.compile(r"\b(leak\w*|water main|hydrant|broken pipe)\b", re.IGNORECASE)
_TREE_DOWN = re.compile(r"\b(fallen|fell|down(ed)?|uproot\w*|blocking|broken|snapped|limb|branch\w*|leaning)\b", re.IGNORECASE)


def utc(ts: str | None) -> datetime | None:
    if not ts:
        return None
    d = datetime.fromisoformat(ts.replace("Z", "+00:00"))
    return (d if d.tzinfo else d.replace(tzinfo=UTC)).astimezone(UTC)


def pacific(ts: str | None) -> datetime | None:
    """DataSF publishes floating Pacific-time timestamps."""
    if not ts:
        return None
    d = datetime.fromisoformat(ts)
    return (d if d.tzinfo else d.replace(tzinfo=PT)).astimezone(UTC)


def classify_text(text: str | None) -> str:
    t = text or ""
    for rx, cat in ((_FLOOD, "flooding"), (_SEWER, "sewer_backup"), (_LEAK, "water_leak"), (_DRAIN, "catch_basin")):
        if rx.search(t):
            return cat
    return "other"


def report_doc(case_id, source, category, requested_at, lat, lon, **fields) -> dict | None:
    if not in_sf(lat, lon):
        return None
    doc = {"_id": f"311:{case_id}", "case_id": case_id, "category": category, "requested_at": requested_at.isoformat(),
           "location": {"lat": lat, "lon": lon}, "h3_9": cell(lat, lon), f"seen_{source}": True}  # fmt: skip
    doc.update({k: (v.isoformat() if isinstance(v, datetime) else v) for k, v in fields.items() if v is not None})
    return doc


RANK = {"keywords": 0, "service_code": 1, "mistral": 2, "datasf": 3}


def merge(old: dict | None, new: dict) -> dict:
    """Two views of one 311 case: the stronger category source wins; the newest status wins."""
    derived = {"zone_100yr", "slr24", "zones"}
    if not old:
        return {k: v for k, v in new.items() if k not in derived}
    out = {k: v for k, v in old.items() if k not in derived}
    better = RANK.get(new.get("category_source"), 0) >= RANK.get(old.get("category_source"), 0)
    newer = (new.get("updated_at") or "") >= (old.get("updated_at") or "")
    for k, v in new.items():
        if k in derived or k == "_id":
            continue
        if k in ("category", "subcategory", "category_source") and not better:
            continue
        if k in ("status", "updated_at") and not newer:
            continue
        out[k] = v
    return out


# ---------------------------------------------------------------- Open311 (live)

OPEN311 = "https://mobile311.sfgov.org/open311/v2/requests.json"
OPEN311_CODES = {"PUC:Water:Sewer": None, "PW:BUF:Tree Maintenance": "tree", "input:Pothole & Street Issues": "street"}


def open311_doc(r: dict) -> dict | None:
    if r.get("lat") is None or not r.get("requested_datetime"):
        return None
    code = r.get("service_code") or ""
    fixed = OPEN311_CODES.get(code)
    desc = r.get("description") or ""
    cat = fixed or classify_text(desc)
    sub = ("fallen_or_damaged" if _TREE_DOWN.search(desc) else "maintenance") if cat == "tree" else None
    return report_doc(str(r["service_request_id"]), "open311", cat, utc(r["requested_datetime"]), float(r["lat"]), float(r["long"]),
                      subcategory=sub, service_code=code, status=r.get("status"), updated_at=utc(r.get("updated_datetime")),
                      address=r.get("address"), description=desc[:2000] or None, media_url=r.get("media_url") or None,
                      category_source="service_code" if fixed else "keywords")  # fmt: skip


def fetch_open311(http: httpx.Client, since: datetime) -> list[dict]:
    out = []
    for code in OPEN311_CODES:
        for page in range(1, 11):
            rows = http.get(OPEN311, params={"service_code": code, "start_date": since.strftime("%Y-%m-%dT%H:%M:%SZ"), "page_size": 200, "page": page}).json()
            out += [d for d in map(open311_doc, rows) if d]
            if len(rows) < 200:
                break
    return out


# ---------------------------------------------------------------- DataSF 311 (history)

DATASF = "https://data.sf.gov/resource/vw6y-z8j6.json"
SEWER_SUB = {"flooding": "flooding", "sewage_back_up": "sewer_backup", "sewage_back-up_discharge": "sewer_backup", "side_sewer_issues": "sewer_backup",
             "water_leak": "water_leak", "water_main_break": "water_leak", "catch_basin": "catch_basin", "catch_basin_other": "catch_basin"}  # fmt: skip
SERVICES = ("Sewer Issues", "Sewer", "Catch Basin Maintenance", "Tree Maintenance", "Street Defects")


def datasf_doc(r: dict) -> dict | None:
    if not r.get("lat") or not r.get("requested_datetime"):
        return None
    name, st = r.get("service_name", ""), (r.get("service_subtype") or "").lower()
    if name in ("Sewer Issues", "Sewer"):
        cat, sub = SEWER_SUB.get(st, "other"), st
    elif name == "Catch Basin Maintenance":
        cat, sub = "catch_basin", st
    elif name == "Tree Maintenance":
        if not any(k in st for k in ("damaged", "damaging", "tree_other")):
            return None
        cat, sub = "tree", "fallen_or_damaged"
    elif name == "Street Defects":
        cat, sub = "street", st
    else:
        return None
    return report_doc(str(r["service_request_id"]), "datasf", cat, pacific(r["requested_datetime"]), float(r["lat"]), float(r["long"]),
                      subcategory=sub, status=(r.get("status_description") or "").lower() or None, updated_at=pacific(r.get("updated_datetime")),
                      closed_at=pacific(r.get("closed_date")), address=r.get("address"), neighborhood=r.get("analysis_neighborhood"),
                      channel=r.get("source"), category_source="datasf")  # fmt: skip


def fetch_datasf(http: httpx.Client, start: datetime, end: datetime | None = None, field: str = "requested_datetime", services=SERVICES):
    names = ",".join(f"'{n}'" for n in services)
    where = f"service_name in ({names}) AND {field} >= '{start.astimezone(PT):%Y-%m-%dT%H:%M:%S}'"
    if end:
        where += f" AND {field} < '{end.astimezone(PT):%Y-%m-%dT%H:%M:%S}'"
    offset = 0
    while True:
        rows = http.get(DATASF, params={"$where": where, "$order": ":id", "$limit": 50000, "$offset": offset}, timeout=180).json()
        yield from (d for d in map(datasf_doc, rows) if d)
        if len(rows) < 50000:
            return
        offset += 50000


# ---------------------------------------------------------------- NWS, NOAA, Open-Meteo, CHP

RELEVANT = {"Flood Watch", "Flood Warning", "Flood Advisory", "Flash Flood Watch", "Flash Flood Warning", "Coastal Flood Advisory",
            "Coastal Flood Watch", "Coastal Flood Warning", "Coastal Flood Statement", "Wind Advisory", "High Wind Warning", "Beach Hazards Statement"}  # fmt: skip
VTEC = {("FA", "A"): "Flood Watch", ("FA", "W"): "Flood Warning", ("FA", "Y"): "Flood Advisory", ("FF", "W"): "Flash Flood Warning",
        ("CF", "Y"): "Coastal Flood Advisory", ("CF", "W"): "Coastal Flood Warning", ("WI", "Y"): "Wind Advisory", ("HW", "W"): "High Wind Warning"}  # fmt: skip


def nws_docs(payload: dict) -> list[dict]:
    out = []
    for f in payload.get("features", []):
        p = f["properties"]
        if p.get("event") not in RELEVANT:
            continue
        s, e = utc(p.get("onset") or p.get("effective")), utc(p.get("ends") or p.get("expires"))
        out.append({"_id": f"nws:{p['id']}", "@timestamp": (utc(p.get("sent")) or s).isoformat(), "kind": "nws_alert", "event": p["event"],
                    "headline": p.get("headline"), "valid_from": s and s.isoformat(), "valid_to": e and e.isoformat(), "url": p.get("@id"), "source": "nws"})  # fmt: skip
    return out


def iem_docs(payload: dict, start: str, end: str, replay: str) -> list[dict]:
    """Archived NWS products (IEM VTEC) overlapping [start, end) for SF zones."""
    seen = {}
    for e in payload.get("events", []):
        ev = VTEC.get((e.get("phenomena"), e.get("significance")))
        if not ev or e.get("ugc") not in SF_UGC or not (e["issue"] < end and e["expire"] > start):
            continue
        key = f"{e['phenomena']}.{e['significance']}.{e['eventid']}"
        seen.setdefault(key, {"_id": f"iem:{replay}:{key}", "@timestamp": e.get("product_issued") or e["issue"], "kind": "nws_alert", "event": ev,
                              "valid_from": e["issue"], "valid_to": e["expire"], "issued_at": e.get("product_issued") or e["issue"],
                              "url": e.get("url"), "source": "iem", "replay": replay})  # fmt: skip
    return list(seen.values())


def tide_docs(payload: dict, kind: str) -> list[dict]:
    rows = payload.get("predictions") or payload.get("data") or []
    out = []
    for p in rows:
        if p.get("v") in (None, ""):
            continue
        t = datetime.strptime(p["t"], "%Y-%m-%d %H:%M").replace(tzinfo=UTC)
        out.append({"_id": f"{kind}:{t:%Y%m%d%H%M}", "@timestamp": t.isoformat(), "kind": kind, "value": float(p["v"]), "tide_type": p.get("type"), "source": "noaa"})
    return out


def weather_docs(payload, now: datetime | None, tag: str = "wx", source: str = "open-meteo", replay: str | None = None) -> list[dict]:
    blocks = payload if isinstance(payload, list) else [payload]
    out = []
    for name, b in zip(POINTS, blocks, strict=False):
        h = b["hourly"]
        for t, r, g in zip(h["time"], h["precipitation"], h.get("wind_gusts_10m") or [None] * len(h["time"]), strict=False):
            ts = datetime.fromisoformat(t).replace(tzinfo=UTC)
            d = {"_id": f"{tag}:{name}:{ts:%Y%m%d%H}", "@timestamp": ts.isoformat(), "kind": "weather", "point": name, "rain_mm": r or 0.0,
                 "gust_kmh": g, "forecast": bool(now and ts > now), "source": source}  # fmt: skip
            if replay:
                d["replay"] = replay
            out.append(d)
    return out


def chp_docs(xml_text: str, now: datetime) -> list[dict]:
    out = []
    for log in ET.fromstring(xml_text).iter("Log"):
        typ = (log.findtext("LogType") or "").strip('"')
        if not any(k in typ for k in ("Traffic Hazard", "CLOSURE", "Flood", "Tree", "Debris")):
            continue
        ll = (log.findtext("LATLON") or "").strip('"')
        if ":" not in ll:
            continue
        lat, lon = int(ll.split(":")[0]) / 1e6, -int(ll.split(":")[1]) / 1e6
        if not in_sf(lat, lon):
            continue
        details = " ".join((d.findtext("IncidentDetail") or "").strip('"') for d in log.iter("details"))
        when = datetime.strptime(" ".join((log.findtext("LogTime") or "").strip('"').split()), "%b %d %Y %I:%M%p").replace(tzinfo=PT)
        out.append({"_id": f"chp:{log.get('ID')}", "type": typ, "location": {"lat": lat, "lon": lon}, "h3_9": cell(lat, lon),
                    "place": (log.findtext("Location") or "").strip('"'), "flooding": bool(re.search(r"flood|water", details + typ, re.IGNORECASE)),
                    "started_at": when.astimezone(UTC).isoformat(), "last_seen": now.isoformat()})  # fmt: skip
    return out


def _pts() -> dict:
    return {"latitude": ",".join(str(p[0]) for p in POINTS.values()), "longitude": ",".join(str(p[1]) for p in POINTS.values()),
            "hourly": "precipitation,wind_gusts_10m", "timezone": "UTC"}  # fmt: skip


FEEDS = {  # name: (interval seconds, index, fetcher(http, since, now) -> docs)
    "open311": (120, "reports", lambda h, since, now: fetch_open311(h, since or now - timedelta(days=2))),
    "nws": (300, "conditions", lambda h, since, now: nws_docs(h.get("https://api.weather.gov/alerts/active", params={"zone": ",".join(SF_UGC)}).json())),
    "weather": (900, "conditions", lambda h, since, now: weather_docs(h.get("https://api.open-meteo.com/v1/forecast", params={**_pts(), "past_days": 1, "forecast_days": 2}).json(), now)),
    "tides": (1800, "conditions", lambda h, since, now: tide_docs(h.get("https://api.tidesandcurrents.noaa.gov/api/prod/datagetter", params={
        "station": "9414290", "product": "predictions", "interval": "hilo", "datum": "MLLW", "units": "english", "time_zone": "gmt", "format": "json",
        "begin_date": f"{now:%Y%m%d}", "range": 48}).json(), "tide_pred")),  # fmt: skip
    "chp": (300, "incidents", lambda h, since, now: chp_docs(h.get("https://media.chp.ca.gov/sa_xml/sa.xml").text, now)),
}


def client() -> httpx.Client:
    return httpx.Client(timeout=30, headers=UA, follow_redirects=True)

"""Storm replay + backtest with no look-ahead, and the per-block history profiles both live and replay use.

A replay dataset is a JSON snapshot of real archived inputs for one Pacific-time day:
  311 reports (DataSF, true request timestamps), observed hourly rain + gusts (Open-Meteo archive at 5 SF points,
  IEM ASOS SFO fallback), NWS products as issued (IEM VTEC archive), observed tide (NOAA 9414290), and block profiles
  computed only from the 5 years *before* that day.
"""

import json
from collections import defaultdict
from datetime import UTC, datetime, timedelta
from pathlib import Path
from zoneinfo import ZoneInfo

from highground import feeds, geo
from highground.risk import RANK, Inputs, assess

PT = ZoneInfo("America/Los_Angeles")
DIR = Path(__file__).resolve().parent.parent / "data" / "replay"
STORM_DAY_MIN = 40  # citywide flood/drain reports in one day that make it a "storm day"
FLOOD = ["flooding", "catch_basin"]


def day_bounds(day: str) -> tuple[datetime, datetime]:
    start = datetime.fromisoformat(day).replace(tzinfo=PT)
    return start.astimezone(UTC), (start + timedelta(days=1)).astimezone(UTC)


# ---------------------------------------------------------------- profiles (ES aggregations + geo_shape msearch)


def storm_days(s, start: datetime, end: datetime) -> list[str]:
    r = s.search("reports", size=0, query={"bool": {"filter": [{"terms": {"category": FLOOD}}, {"range": {"requested_at": {"gte": start.isoformat(), "lt": end.isoformat()}}}]}},
                 aggs={"d": {"date_histogram": {"field": "requested_at", "calendar_interval": "day", "time_zone": "America/Los_Angeles", "min_doc_count": STORM_DAY_MIN}}})  # fmt: skip
    return [b["key_as_string"][:10] for b in r["aggregations"]["d"]["buckets"]]


def zone_flags(s, cells: list[str]) -> dict[str, dict]:
    out = {}
    for i in range(0, len(cells), 200):
        chunk, body = cells[i : i + 200], []
        for c in chunk:
            lat, lon = geo.center(c)
            body += [{"index": s.ix("zones")}, {"size": 0, "query": {"geo_shape": {"geometry": {"shape": {"type": "point", "coordinates": [lon, lat]}, "relation": "intersects"}}},
                                                "aggs": {"l": {"terms": {"field": "layer"}}, "n": {"terms": {"field": "name", "size": 1, "exclude": ["100yr", "slr24"]}}}}]  # fmt: skip
        for c, r in zip(chunk, s.es.msearch(searches=body)["responses"], strict=False):
            layers = {b["key"] for b in r.get("aggregations", {}).get("l", {}).get("buckets", [])}
            nb = r.get("aggregations", {}).get("n", {}).get("buckets", [])
            out[c] = {"in_100yr": "100yr" in layers, "slr24": "slr24" in layers, "neighborhood": nb[0]["key"] if nb else None}
    return out


def build_profiles(s, as_of: datetime, index: str | None = None) -> dict:
    """Per-cell storm history from the 5 years before as_of only (so a replay never sees its own storm)."""
    start = as_of - timedelta(days=5 * 365)
    days = storm_days(s, start, as_of)
    counts: dict[str, int] = defaultdict(int)
    if days:
        should = [{"range": {"requested_at": {"gte": f"{d}T00:00:00", "lt": f"{d}T23:59:59", "time_zone": "America/Los_Angeles"}}} for d in days]
        r = s.search("reports", size=0, query={"bool": {"filter": [{"terms": {"category": FLOOD}}, {"bool": {"should": should, "minimum_should_match": 1}}]}},
                     aggs={"c": {"terms": {"field": "h3_9", "size": 20000}}})  # fmt: skip
        counts.update({b["key"]: b["doc_count"] for b in r["aggregations"]["c"]["buckets"]})
    flood_cells = s.search("reports", size=0, query={"term": {"zone_100yr": True}}, aggs={"c": {"terms": {"field": "h3_9", "size": 20000}}})["aggregations"]["c"]["buckets"]
    cells = sorted(set(counts) | {b["key"] for b in flood_cells})
    flags = zone_flags(s, cells)
    profiles = {}
    for c in cells:
        ring = sum(counts.get(n, 0) for n in geo.disk(c, 1))
        lat, lon = geo.center(c)
        profiles[c] = {"h3_9": c, "storm_reports_5y": ring, "storm_days_5y": len(days), **flags[c], "centroid": {"lat": lat, "lon": lon}}
    if index:
        s.write(index, [{"_id": c, **p} for c, p in profiles.items()], refresh=True)
    return {"cells": len(profiles), "storm_days": len(days), "profiles": profiles if not index else None}


# ---------------------------------------------------------------- dataset (real archived inputs, fetched once)


def _weather(http, day: str) -> tuple[list[dict], str]:
    p = {"latitude": ",".join(str(v[0]) for v in geo.POINTS.values()), "longitude": ",".join(str(v[1]) for v in geo.POINTS.values()),
         "hourly": "precipitation,wind_gusts_10m", "timezone": "UTC", "start_date": (datetime.fromisoformat(day) - timedelta(days=1)).date().isoformat(),
         "end_date": (datetime.fromisoformat(day) + timedelta(days=1)).date().isoformat()}  # fmt: skip
    r = http.get("https://archive-api.open-meteo.com/v1/archive", params=p, timeout=60)
    if r.status_code == 200:
        return feeds.weather_docs(r.json(), None, tag=f"replay{day}", source="open-meteo-archive", replay=day), "Open-Meteo ERA5 archive (5 SF points)"
    # fallback: SFO airport gauge (IEM ASOS), applied to every point
    a = http.get("https://mesonet.agron.iastate.edu/cgi-bin/request/asos.py", params={"station": "SFO", "data": "p01i", "tz": "Etc/UTC", "format": "onlycomma",
                 "year1": p["start_date"][:4], "month1": p["start_date"][5:7], "day1": p["start_date"][8:], "year2": p["end_date"][:4], "month2": p["end_date"][5:7],
                 "day2": p["end_date"][8:], "report_type": "3"}, timeout=60).text  # fmt: skip
    hourly: dict[str, float] = defaultdict(float)
    for line in a.splitlines()[1:]:
        parts = line.split(",")
        if len(parts) >= 3 and parts[2] not in ("M", "T", ""):
            hourly[parts[1][:13]] = max(hourly[parts[1][:13]], float(parts[2]) * 25.4)
    out = []
    for name in geo.POINTS:
        for h, mm in hourly.items():
            out.append({"@timestamp": datetime.fromisoformat(h + ":00").replace(tzinfo=UTC).isoformat(), "kind": "weather", "point": name, "rain_mm": mm, "gust_kmh": None})
    return out, "IEM ASOS SFO airport gauge (Open-Meteo unavailable)"


def build_dataset(s, http, day: str) -> dict:
    start, end = day_bounds(day)
    reports = [d for d in feeds.fetch_datasf(http, start - timedelta(hours=6), end + timedelta(hours=6), services=("Sewer Issues", "Sewer", "Catch Basin Maintenance", "Tree Maintenance"))]
    weather, wsrc = _weather(http, day)
    y = day[:4]
    iem = http.get("https://mesonet.agron.iastate.edu/json/vtec_events_bywfo.py", params={"wfo": "MTR", "year": y}, timeout=60).json()
    nws = feeds.iem_docs(iem, (start - timedelta(days=2)).isoformat().replace("+00:00", "Z"), end.isoformat().replace("+00:00", "Z"), day)
    tide = http.get("https://api.tidesandcurrents.noaa.gov/api/prod/datagetter", params={"station": "9414290", "product": "hourly_height", "datum": "MLLW",
                    "units": "english", "time_zone": "gmt", "format": "json", "begin_date": (start - timedelta(hours=6)).strftime("%Y%m%d %H:%M"),
                    "end_date": (end + timedelta(hours=6)).strftime("%Y%m%d %H:%M")}, timeout=60).json()  # fmt: skip
    prof = build_profiles(s, start)
    ds = {"day": day, "built_at": datetime.now(UTC).isoformat(), "weather_source": wsrc,
          "reports": [{k: r.get(k) for k in ("case_id", "category", "subcategory", "requested_at", "location", "h3_9", "address", "neighborhood", "status")} for r in reports],
          "weather": [{k: w.get(k) for k in ("@timestamp", "point", "rain_mm", "gust_kmh")} for w in weather],
          "nws": [{k: n.get(k) for k in ("event", "valid_from", "valid_to", "issued_at", "url")} for n in nws],
          "tide": [{"t": t["@timestamp"], "ft": t["value"]} for t in feeds.tide_docs(tide, "tide_obs")],
          "profiles": prof["profiles"], "storm_days_before": prof["storm_days"]}  # fmt: skip
    DIR.mkdir(parents=True, exist_ok=True)
    (DIR / f"{day}.json").write_text(json.dumps(ds))
    return {"day": day, "reports": len(ds["reports"]), "weather": len(ds["weather"]), "nws": len(ds["nws"]), "tide": len(ds["tide"]), "cells": len(ds["profiles"]), "weather_source": wsrc}


def load(day: str) -> dict:
    return json.loads((DIR / f"{day}.json").read_text())


# ---------------------------------------------------------------- as-of inputs (strict cutoff = no look-ahead)


class Replay:
    def __init__(self, ds: dict):
        self.ds = ds
        self.rain: dict[str, list[tuple[datetime, float, float]]] = defaultdict(list)
        for w in ds["weather"]:
            self.rain[w["point"]].append((datetime.fromisoformat(w["@timestamp"]), w["rain_mm"] or 0.0, w["gust_kmh"] or 0.0))
        self.reports = sorted(((datetime.fromisoformat(r["requested_at"]), r) for r in ds["reports"]), key=lambda x: x[0])
        self.tide = [(datetime.fromisoformat(t["t"]), t["ft"]) for t in ds["tide"]]

    def inputs(self, c: str, t: datetime, active_cells: dict | None = None) -> Inputs:
        p = self.ds["profiles"].get(c, {})
        lat, lon = geo.center(c)
        pt = geo.nearest_point(lat, lon)
        # hourly totals are labeled by hour start; an hour counts as observed only once it has ended
        obs = [(ts, mm, g) for ts, mm, g in self.rain[pt] if ts + timedelta(hours=1) <= t]
        r1 = sum(mm for ts, mm, _ in obs if ts >= t - timedelta(hours=1, minutes=59))
        r3 = sum(mm for ts, mm, _ in obs if ts >= t - timedelta(hours=3, minutes=59))
        gust = max((g for ts, _, g in obs if ts >= t - timedelta(hours=3)), default=0.0)
        z = lambda d: d.isoformat().replace("+00:00", "Z")
        # a product counts once issued, while valid, or if it starts within 12 h (a watch issued ahead of the storm)
        nws = sorted({n["event"] for n in self.ds["nws"] if n["issued_at"] <= z(t) < n["valid_to"] and n["valid_from"] <= z(t + timedelta(hours=12))})
        ring = set(geo.disk(c, 1))
        near = [(r["category"], (t - ts).total_seconds() / 3600) for ts, r in self.reports if ts <= t and ts > t - timedelta(hours=6) and r["h3_9"] in ring]
        tide = max((ft for ts, ft in self.tide if t - timedelta(hours=1) <= ts <= t), default=None)
        return Inputs(in_100yr=p.get("in_100yr", False), slr24=p.get("slr24", False), storm_reports_5y=p.get("storm_reports_5y", 0), rain_1h=r1, rain_3h=r3,
                      gust_kmh=gust, nws=nws, tide_ft=tide, reports=near, rain_point=pt,
                      sources={"rain_3h": self.ds["weather_source"], "nws": "NWS via IEM VTEC archive", "reports": "DataSF 311 (vw6y-z8j6)",
                               "tide": "NOAA 9414290", "history": "DataSF 311, 5 years before this day", "zone_100yr": "DataSF jzu3-4yxp"})  # fmt: skip

    def cells(self) -> list[str]:
        return sorted(set(self.ds["profiles"]) | {r["h3_9"] for _, r in self.reports if r["category"] in FLOOD})

    def frame(self, t: datetime) -> dict:
        out = {}
        for c in self.cells():
            r = assess(self.inputs(c, t), t)
            if r.level != "low":
                out[c] = {"level": r.level, "score": r.score}
        rep = [{"h3_9": r["h3_9"], "category": r["category"], "at": ts.isoformat(), "lat": r["location"]["lat"], "lon": r["location"]["lon"]}
               for ts, r in self.reports if ts <= t and ts > t - timedelta(hours=6)]  # fmt: skip
        return {"t": t.isoformat(), "cells": out, "reports": rep}


def backtest(ds: dict, step_min: int = 15, threshold: str = "high") -> dict:
    """Lead time = first report on/next to a block minus the first time the engine flagged it >= threshold (as of then)."""
    rp = Replay(ds)
    start, end = day_bounds(ds["day"])
    cells = rp.cells()
    first_flag: dict[str, datetime] = {}
    t = start
    while t < end:
        for c in cells:
            if c not in first_flag and RANK[assess(rp.inputs(c, t), t).level] >= RANK[threshold]:
                first_flag[c] = t
        t += timedelta(minutes=step_min)
    first_report: dict[str, datetime] = {}
    for ts, r in rp.reports:
        if start <= ts < end and r["category"] in FLOOD:
            for n in geo.disk(r["h3_9"], 1):
                first_report.setdefault(n, ts)
    hit_cells = {r["h3_9"] for ts, r in rp.reports if start <= ts < end and r["category"] in FLOOD}
    leads = []
    for c in hit_cells:
        own = min(ts for ts, r in rp.reports if r["h3_9"] == c and r["category"] in FLOOD and start <= ts < end)
        if c in first_flag:
            leads.append((own - first_flag[c]).total_seconds() / 60)
    flagged_ok = sum(1 for c in first_flag if c in first_report and first_report[c] <= first_flag[c] + timedelta(hours=6))
    leads.sort()
    return {"day": ds["day"], "threshold": threshold, "blocks_with_flood_reports": len(hit_cells), "flagged_before_or_at_report": sum(1 for x in leads if x >= 0),
            "flagged_after_report": sum(1 for x in leads if x < 0), "never_flagged": len(hit_cells) - len(leads),
            "median_lead_min": leads[len(leads) // 2] if leads else None, "flagged_blocks": len(first_flag),
            "false_alarm_blocks": len(first_flag) - flagged_ok, "first_flag": min(first_flag.values()).isoformat() if first_flag else None,
            "first_report": min(first_report.values()).isoformat() if first_report else None, "weather_source": ds["weather_source"]}  # fmt: skip

"""HighGround SF web app: briefing, ask, report, map tiles, replay/backtest, status. Reads only Elasticsearch + Mistral."""

import logging
from datetime import UTC, datetime, timedelta
from functools import lru_cache
from pathlib import Path

from fastapi import FastAPI, File, Form, HTTPException, Query, UploadFile
from fastapi.responses import FileResponse, JSONResponse, Response
from fastapi.staticfiles import StaticFiles
from pydantic import BaseModel

from highground import briefing as br
from highground import geo, layers, replay, store
from highground.feeds import FEEDS

logging.basicConfig(level=logging.INFO)
app = FastAPI(title="HighGround SF", version="hacknight")
WEB = Path(__file__).parent / "web"


@lru_cache
def S() -> store.Store:
    return store.Store()


def locate(address: str | None, lat: float | None, lon: float | None) -> dict:
    if lat is not None and lon is not None:
        if not geo.in_sf(lat, lon):
            raise HTTPException(422, "That point is outside San Francisco.")
        return {"lat": lat, "lon": lon, "label": f"{lat:.5f}, {lon:.5f}"}
    if not address:
        raise HTTPException(422, "Give an address, an intersection, or lat/lon.")
    g = layers.geocode(S(), address)
    if not g:
        raise HTTPException(404, f"Could not find '{address}' in San Francisco. Try an intersection like '17th and Folsom'.")
    return g


@app.get("/api/briefing")
def get_briefing(address: str | None = None, lat: float | None = None, lon: float | None = None, lang: str = "en"):
    g = locate(address, lat, lon)
    return br.briefing(S(), g["lat"], g["lon"], g["label"], lang)


@app.get("/api/geocode")
def get_geocode(q: str):
    return locate(q, None, None)


class Ask(BaseModel):
    question: str
    lang: str | None = None
    lat: float | None = None
    lon: float | None = None


@app.post("/api/ask")
def post_ask(a: Ask):
    from highground import agent

    return agent.ask(S(), a.question, a.lat, a.lon)


@app.post("/api/report")
async def post_report(lat: float = Form(...), lon: float = Form(...), text: str = Form(""), photo: UploadFile | None = File(None), audio: UploadFile | None = File(None)):
    from highground import report

    img = await photo.read() if photo else None
    snd = await audio.read() if audio else None
    if (img and len(img) > 8_000_000) or (snd and len(snd) > 10_000_000):
        raise HTTPException(413, "File too large")
    return report.draft(S(), lat, lon, text, img, photo.content_type if photo else None, snd)


@app.get("/api/nearby")
def nearby(lat: float, lon: float, hours: int = Query(24, le=168), radius_m: int = Query(500, le=3000)):
    """Text twin of the map: every recent report near a point, closest first."""
    r = S().search("reports", size=100, sort=[{"_geo_distance": {"location": {"lat": lat, "lon": lon}, "order": "asc", "unit": "m"}}],
                   query={"bool": {"filter": [{"geo_distance": {"distance": f"{radius_m}m", "location": {"lat": lat, "lon": lon}}},
                                              {"range": {"requested_at": {"gte": f"now-{hours}h"}}}]}},
                   _source=["category", "requested_at", "address", "status", "location"])  # fmt: skip
    return [{**h["_source"], "distance_m": round(h["sort"][0])} for h in r["hits"]["hits"]]


@app.get("/tiles/{layer}/{z}/{x}/{y}.pbf")
def tiles(layer: str, z: int, x: int, y: int, hours: int = 72):
    """Vector tiles straight from Elasticsearch _mvt (points + H3 geohex aggregation)."""
    if layer == "reports":
        body = {"grid_agg": "geohex", "grid_precision": 4, "size": 2000, "fields": ["category", "requested_at", "status"],
                "query": {"range": {"requested_at": {"gte": f"now-{hours}h"}}}}  # fmt: skip
        idx, field = "reports", "location"
    elif layer == "history":
        body = {"grid_agg": "geohex", "grid_precision": 6, "size": 0, "query": {"terms": {"category": ["flooding", "catch_basin"]}}}
        idx, field = "reports", "location"
    elif layer == "zones":
        body = {"size": 5000, "grid_precision": 0, "fields": ["layer"], "query": {"term": {"layer": "100yr"}}}
        idx, field = "zones", "geometry"
    else:
        raise HTTPException(404)
    try:
        data = S().es.search_mvt(index=S().ix(idx), field=field, zoom=z, x=x, y=y, **body)
    except Exception as exc:
        raise HTTPException(502, str(exc)[:200]) from exc
    return Response(bytes(data.body), media_type="application/vnd.mapbox-vector-tile", headers={"Cache-Control": "max-age=60"})


@lru_cache(maxsize=4)
def _replay(day: str) -> replay.Replay:
    return replay.Replay(replay.load(day))


@app.get("/api/replay/{day}")
def get_replay(day: str, t: str | None = None):
    try:
        rp = _replay(day)
    except FileNotFoundError as exc:
        raise HTTPException(404, f"No replay dataset for {day}. Run: python -m highground.ingest replay {day}") from exc
    start, end = replay.day_bounds(day)
    if not t:
        hours = []
        for h in range(24):
            ts = start + timedelta(hours=h)
            rain = sum(w[1] for w in rp.rain.get("c", []) if ts <= w[0] < ts + timedelta(hours=1))
            n = sum(1 for x, r in rp.reports if ts <= x < ts + timedelta(hours=1) and r["category"] in replay.FLOOD)
            hours.append({"t": ts.isoformat(), "rain_mm": round(rain, 1), "flood_reports": n})
        return {"day": day, "start": start.isoformat(), "end": end.isoformat(), "hours": hours, "weather_source": rp.ds["weather_source"],
                "nws": rp.ds["nws"], "cells": len(rp.cells())}  # fmt: skip
    ts = datetime.fromisoformat(t.replace("Z", "+00:00"))
    f = rp.frame(ts if ts.tzinfo else ts.replace(tzinfo=UTC))
    f["polygons"] = {c: geo.polygon(c) for c in f["cells"]}
    return f


@lru_cache(maxsize=8)
def _backtest(day: str, threshold: str) -> dict:
    return replay.backtest(replay.load(day), threshold=threshold)


@app.get("/api/backtest/{day}")
def get_backtest(day: str, threshold: str = "high"):
    return _backtest(day, threshold)


@lru_cache(maxsize=4)
def _ops(bucket: int, hours: int) -> dict:
    from highground import ops

    return {"hours": hours, "citywide": ops.citywide(S(), hours), "hotspots": ops.hotspots_now(S(), hours), "summary": ops.summary(S(), hours)}


@app.get("/api/ops")
def get_ops(hours: int = Query(72, ge=1, le=720)):
    return _ops(int(datetime.now(UTC).timestamp() // 300), hours)  # 5-minute cache: COMPLETION calls Mistral


@app.get("/status")
def status():
    out = {}
    for name, (interval, _, _) in FEEDS.items():
        st = S().feed_state(name)
        age = (datetime.now(UTC) - datetime.fromisoformat(st["last_ok"])).total_seconds() if st.get("last_ok") else None
        out[name] = {"age_s": round(age) if age is not None else None, "fresh": age is not None and age < 3 * interval, "error": st.get("error")}
    return {"feeds": out, "mistral": S().cfg.has_mistral}


@app.get("/healthz")
def healthz():
    try:
        S().es.info()
        return {"ok": True}
    except Exception as exc:  # noqa: BLE001
        return JSONResponse({"ok": False, "error": type(exc).__name__}, 503)


@app.on_event("startup")
def warm():
    import threading

    threading.Thread(target=lambda: [_backtest(d.stem, "high") for d in replay.DIR.glob("*.json")], daemon=True).start()


app.mount("/static", StaticFiles(directory=WEB), name="static")


